using System.Collections.Generic;
using System.Linq;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CharacterProgression", menuName = "Data/Characters/CharacterProgression")]
public class CharacterProgression : ScriptableObject
{
	[Header("Character Levels")]
	[SerializeField]
	private CharacterLevelUnlockables[] characterLevelUnlockables;

	[Header("Assets")]
	[SerializeField]
	private CharacterLevelTable characterLevelTable;

	[Header("First Check Picks")]
	[SerializeField]
	private bool enableFirstChestPicksStrings;

	[SerializeField]
	[ShowIf("enableFirstChestPicksStrings")]
	private FirstChestPicksString[] firstChestPicksStrings;

	[Header("Character Percentage Progression")]
	[SerializeField]
	private PlayerProgressionData playerProgressionData;

	[SerializeField]
	private AchievementsList achievementsList;

	[SerializeField]
	private DifficultyLevels difficultyLevels;

	[SerializeField]
	private AllPlayerDicesList allPlayerDicesList;

	[SerializeField]
	private OmensListsList omensListsList;

	[SerializeField]
	private CompanionsListsList companionsListsList;

	[Header("Character Progression")]
	public bool CharacterUnlocked;

	public int CharacterXP;

	public bool AstreaHeartReached;

	public int CurrentAnomalyLevel;

	public int UnlockedAnomalyLevel;

	public int CurrentAstreaLevel;

	public int UnlockedAstreaLevel;

	public bool MaxNonHiddenAnomalyLevelDefeated;

	public bool MaxNonHiddenAstreaLevelDefeated;

	public bool MaxNonHiddenAnomalyAndAstreaDefeatedAtTheSameTime;

	public bool AnomalyLevelHiddenDefeated;

	public bool AstreaLevelHiddenDefeated;

	public int FirstChestPicksCounter;

	public float CharacterProgressionPercentage;

	public List<int> AnomalyLevelsDefeated;

	public List<int> AstreaLevelsDefeated;

	public CharacterLevelUnlockables[] CharacterLevelUnlockables => characterLevelUnlockables;

	public bool EnableFirstChestPicksStrings => enableFirstChestPicksStrings;

	public FirstChestPicksString[] FirstChestPicksStrings => firstChestPicksStrings;

	public int GetCharacterLevel(Character character)
	{
		return characterLevelTable.GetCharacterLevel(character);
	}

	public int GetCharacterCurrentLevelXP(int characterLevel)
	{
		return characterLevelTable.GetCharacterCurrentLevelXP(characterLevel, CharacterXP);
	}

	public int GetCharacterNextLevelXP(int characterLevel)
	{
		return characterLevelTable.GetCharacterNextLevelXP(characterLevel);
	}

	public List<DiceFace> GetLockedDiceFaces(Character character)
	{
		List<DiceFace> list = new List<DiceFace>();
		int characterLevel = GetCharacterLevel(character);
		if (characterLevel < characterLevelUnlockables.Length)
		{
			for (int i = 0; i < characterLevelUnlockables.Length; i++)
			{
				if (i < characterLevel)
				{
					continue;
				}
				for (int j = 0; j < characterLevelUnlockables[i].diceFaces.Length; j++)
				{
					if (!characterLevelUnlockables[i].diceFacesToIgnoreLock.Contains(j))
					{
						list.Add(characterLevelUnlockables[i].diceFaces[j]);
					}
				}
			}
		}
		return list;
	}

	public List<string> GetLockedDiceNames(Character character)
	{
		List<string> list = new List<string>();
		int characterLevel = GetCharacterLevel(character);
		if (characterLevel < characterLevelUnlockables.Length)
		{
			for (int i = 0; i < characterLevelUnlockables.Length; i++)
			{
				if (i >= characterLevel)
				{
					list.AddRange(characterLevelUnlockables[i].diceNames);
				}
			}
		}
		return list;
	}

	public List<OmenData> GetLockedOmenDatas(Character character)
	{
		List<OmenData> list = new List<OmenData>();
		int characterLevel = GetCharacterLevel(character);
		if (characterLevel < characterLevelUnlockables.Length)
		{
			for (int i = 0; i < characterLevelUnlockables.Length; i++)
			{
				if (i >= characterLevel)
				{
					list.AddRange(characterLevelUnlockables[i].omenDatas);
				}
			}
		}
		return list;
	}

	public CharacterLevelUnlockables GetCharacterLevelUnlockablesUnlockCharacterOnCurrentOrLowerLevels(int characterLevel)
	{
		for (int i = 0; i < characterLevelUnlockables.Length; i++)
		{
			if (i > characterLevel - 1)
			{
				return null;
			}
			if (characterLevelUnlockables[i].unlockCharacter)
			{
				return characterLevelUnlockables[i];
			}
		}
		return null;
	}

	public int GetXPSumAmount()
	{
		return characterLevelTable.GetXPSumAmount();
	}

	public void SetCharacterPercentageProgression(Character character)
	{
		CharacterProgressionPercentage = 0f;
		CharacterProgressionPercentage += GetCharacterNonNeutralPercentage(character);
		float characterUnlockedAchievementsPercentage = achievementsList.GetCharacterUnlockedAchievementsPercentage(character);
		CharacterProgressionPercentage += characterUnlockedAchievementsPercentage * playerProgressionData.AchievementsPercentage;
		int allPlayerDiceDiscoveredFromCharacterTotal = allPlayerDicesList.GetAllPlayerDiceDiscoveredFromCharacterTotal(character);
		int allPlayerDiceFromCharacterTotalWithoutTutorialAndDebug = allPlayerDicesList.GetAllPlayerDiceFromCharacterTotalWithoutTutorialAndDebug(character);
		float characterBlessingsDiscoveredAmount = omensListsList.GetCharacterBlessingsDiscoveredAmount(character);
		int count = omensListsList.GetOmensList(character).OmenDatas.Count;
		float characterSentinelDiscoveredAmount = companionsListsList.GetCharacterSentinelDiscoveredAmount(character);
		int count2 = companionsListsList.GetCompanionsList(character).Companions.Count;
		float num = (float)allPlayerDiceDiscoveredFromCharacterTotal + characterBlessingsDiscoveredAmount + characterSentinelDiscoveredAmount;
		float num2 = allPlayerDiceFromCharacterTotalWithoutTutorialAndDebug + count + count2;
		CharacterProgressionPercentage += num / num2 * playerProgressionData.DiscoverSystemPercentage;
	}

	public float GetCharacterNonNeutralPercentage(Character character)
	{
		float num = 0f;
		if (AstreaHeartReached)
		{
			num += playerProgressionData.AstreasHeartReachedPercentage;
		}
		if (character.CharacterAchievement.HeroAchievementData.IsUnlocked())
		{
			num += playerProgressionData.AstreaDefeatedPercentage;
		}
		float num2 = (float)CharacterXP / (float)GetXPSumAmount();
		num += num2 * playerProgressionData.CharacterLevelUpPercentage;
		int difficultyLevelsAmountWithoutHidden = difficultyLevels.GetDifficultyLevelsAmountWithoutHidden(getAnomalyLevel: true);
		int num3 = -1;
		num3 = ((UnlockedAnomalyLevel != -1 && UnlockedAnomalyLevel != 0) ? ((!MaxNonHiddenAnomalyLevelDefeated) ? (UnlockedAnomalyLevel - 1) : difficultyLevelsAmountWithoutHidden) : 0);
		float num4 = (float)num3 / (float)difficultyLevelsAmountWithoutHidden;
		num += num4 * playerProgressionData.AnomalyLevelPercentage;
		int difficultyLevelsAmountWithoutHidden2 = difficultyLevels.GetDifficultyLevelsAmountWithoutHidden(getAnomalyLevel: false);
		int num5 = -1;
		num5 = ((UnlockedAstreaLevel != -1 && UnlockedAstreaLevel != 0) ? ((!MaxNonHiddenAstreaLevelDefeated) ? (UnlockedAstreaLevel - 1) : difficultyLevelsAmountWithoutHidden2) : 0);
		float num6 = (float)num5 / (float)difficultyLevelsAmountWithoutHidden2;
		num += num6 * playerProgressionData.AstreaLevelPercentage;
		if (AnomalyLevelHiddenDefeated)
		{
			num += playerProgressionData.HiddenDifficultyLevelsPercentage;
		}
		if (AstreaLevelHiddenDefeated)
		{
			num += playerProgressionData.HiddenDifficultyLevelsPercentage;
		}
		return num;
	}
}
